# Graph Builder Role

You receive a list of source files from a single module (directory) and their
contents. Respond with exactly two tagged lines — no prose, no preamble, nothing else.

## Output format

```
GRAPH_SUMMARY:<one paragraph — what this module does and why it exists>
GRAPH_SUBSYSTEM:<single word grouping — e.g. auth, billing, api, storage, graph, wiki, cli>
```

Rules:
- GRAPH_SUMMARY: one paragraph, no bullets, plain prose
- GRAPH_SUBSYSTEM: one word only
- Output exactly these two lines. Nothing else.


Module path: frontends/ui
Files:

--- frontends/ui/.eslintrc.cjs (30 lines) ---
module.exports = {
  root: true,
  extends: ['../eslint-base.cjs'],
  rules: {
    '@typescript-eslint/no-unused-vars': ['error', { argsIgnorePattern: '^_', varsIgnorePattern: '^_' }],
    // NOTE: no `react/jsx-no-literals` here. Unlike the MFEs, @omnicore-platform/ui
    // ships string-agnostic primitives — all user-facing copy is passed in by
    // the consuming MFE as props (which IS keyed via m.*() at the call site).
    // A primitive never hardcodes a translatable string.
  },
  overrides: [
    {
      // Test fixtures build throwaway markup — mock surfaces wired with
      // onClick/onKeyDown to drive a hook or assert event bubbling, and
      // deliberately-invalid role props on stub components exercising
      // bad-input handling — not real interactive UI. The a11y
      // interaction/role rules don't apply to test scaffolding — relax them
      // here so genuine issues in src/ still surface.
      files: ['tests/**/*.ts', 'tests/**/*.tsx'],
      rules: {
        'jsx-a11y/click-events-have-key-events': 'off',
        'jsx-a11y/no-noninteractive-element-interactions': 'off',
        'jsx-a11y/no-static-element-interactions': 'off',
        'jsx-a11y/aria-role': 'off',
      },
    },
  ],
  ignorePatterns: ['dist', 'node_modules'],
}


--- frontends/ui/postcss.config.js (13 lines) ---
// Storybook build's PostCSS pipeline (Task 3.1). Mirrors every MFE's
// postcss.config.cjs (tailwindcss + autoprefixer) — written as ESM (not
// .cjs) because frontends/ui/package.json declares "type": "module" and
// postcss-load-config (which Vite's built-in CSS pipeline uses to discover
// this file) resolves a plain .js config through the package's own module
// type.
export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};


--- frontends/ui/tailwind.config.ts (31 lines) ---
import type { Config } from "tailwindcss";
import cogPreset from "./tailwind.preset";

// Storybook-only Tailwind config (Task 3.1). @omnicore-platform/ui itself is
// a source-only package with no build step — every consuming MFE brings its
// own tailwind.config.ts (see e.g. ../admin-mfe/tailwind.config.ts) that
// applies this package's shared `cogPreset`. Storybook is the first
// standalone BUILD of this package, so it needs the same wiring: the shared
// preset plus a `content` glob scoped to `.storybook/` + `stories/` + `src/`
// (stories/ is NOT under src/ — see stories/README notes in the Storybook
// config — so it must be listed explicitly or its cog-* classes never reach
// the JIT scanner).
export default {
  presets: [cogPreset],
  content: [
    "./.storybook/**/*.{ts,tsx}",
    "./stories/**/*.{ts,tsx}",
    "./src/**/*.{ts,tsx}",
    // platform-chrome is scanned for parity with every consuming MFE's config
    // (check-ui-guardrails enforces this glob repo-wide). Storybook does not
    // currently render chrome components, but a story that does must not
    // silently lose their cog-* classes to the JIT.
    "../platform-chrome/src/**/*.{ts,tsx}",
    // Paraglide emits one .js AND one .d.ts per message key — 12,536 files,
    // none carrying a class name. Excluding them emits byte-identical CSS and
    // removes that scan from every build (see kite-mfe's config for the same
    // exclusion and its measured impact).
    "!../platform-chrome/src/paraglide/generated/**",
  ],
} satisfies Config;


--- frontends/ui/tailwind.preset.ts (928 lines) ---
import type { Config } from "tailwindcss";

// ─────────────────────────────────────────────────────────────────────────
// CogOS 3.0 shared Tailwind preset — single source of truth for the cog-*
// design-system tokens consumed by every MFE.
//
// See docs/design/design.md §16 for the canonical token mapping. This preset
// is the UNION SUPERSET of the five previously-drifted per-MFE tailwind
// configs (shell / admin / dialogue / files / range): every token any MFE
// defined is present here so no MFE loses a token when it switches to
// `presets: [cogPreset]`.
//
// Theme-switchable colors (surfaces, text, borders, focus, the bare
// `cog-warning` DEFAULT) read CSS variables defined per-MFE in
// src/styles/index.css and are written `rgb(var(--token) / <alpha-value>)`
// so Tailwind's opacity utilities work. Brand + status ramps are literal
// values; components pick the right stop per mode via the `dark:` variant.
//
// Conflict notes (values that differed across MFEs, resolved here):
//   • cog-success.300 → #34D399  (admin's value; the only MFE that uses the
//     300 stop — dialogue/range use cog-green-300 instead, unaffected).
//   • cog-danger.700  → #5C0B0B  (majority: dialogue/files/range). admin
//     uses #7A0F0F and keeps a one-line local override in its own config.
//   • cog-blue.900    → #0F2A6B  (range's value; serves both the light-mode
//     `text-cog-blue-900` and the dark-mode `bg-cog-blue-900/20` call sites
//     that previously rendered nothing where the stop was undefined).
//   • cog-green.900   → #0B2F22  (matches the dark-bg tint dialogue/range
//     were already approximating via `dark:bg-[#0B2F22]`).
// ─────────────────────────────────────────────────────────────────────────

const cogPreset = {
  darkMode: ["variant", [
    "&:where(.dark, .dark *)",
    '&:where([data-theme="dark"], [data-theme="dark"] *)',
  ]],
  theme: {
    extend: {
      colors: {
        // ── Theme-switchable (CSS-variable) tokens ──────────────────────
        "cog-canvas": "rgb(var(--cog-canvas) / <alpha-value>)",
        "cog-surface": "rgb(var(--cog-surface) / <alpha-value>)",
        "cog-surface-subtle": "rgb(var(--cog-surface-subtle) / <alpha-value>)",
        "cog-surface-muted": "rgb(var(--cog-surface-muted) / <alpha-value>)",
        "cog-skeleton": "rgb(var(--cog-skeleton) / <alpha-value>)",
        "cog-text-primary": "rgb(var(--cog-text-primary) / <alpha-value>)",
        "cog-text-secondary": "rgb(var(--cog-text-secondary) / <alpha-value>)",
        "cog-text-tertiary": "rgb(var(--cog-text-tertiary) / <alpha-value>)",
        "cog-text-eyebrow": "rgb(var(--cog-text-eyebrow) / <alpha-value>)",
        "cog-border": "rgb(var(--cog-border) / <alpha-value>)",
        "cog-divider": "rgb(var(--cog-divider) / <alpha-value>)",
        "cog-focus": "rgb(var(--cog-focus) / <alpha-value>)",

        // Task 5.2: theme-aware 3rd border tier (stronger than cog-border,
        // ≥3:1 in both themes) — CSS-variable backed like cog-border/
        // cog-divider above, unlike the static dark-only token below. Ready
        // for range-mfe's `cog-border-strong` call sites (BentoGrid.tsx,
        // FocusCanvas.tsx :264/:311), which reference a class that doesn't
        // exist yet — migrating those sites is Task 2.5a/7.3's, not this one's.
        "cog-border-emphasized": "rgb(var(--cog-border-emphasized) / <alpha-value>)",

        // Dark-only emphasized border (design.md §6 e4/e5). Always use with
        // a `dark:` prefix — not a CSS variable because it is dark-mode only.
        // Task 5.2: raised #3F4A60 (1.16-2.17:1, failed the 3:1 floor) to
        // #94A3B8 (5.97-7.53:1) — the same value cog-border-emphasized
        // carries for dark mode above.
        "cog-border-dark-emphasized": "#94A3B8",
        "cog-scrim": "rgba(15,23,42,0.45)",
        "cog-scrim-dark": "rgba(0,0,0,0.65)",

        // NOTE (#2305): the Switch/Toggle off-state track leans on
        // `cog-border-emphasized` above, which the design-tokens pipeline
        // already emits theme-aware (light #475569, dark #94A3B8 — 6.66:1 /
        // 5.97:1, both clear of WCAG 1.4.11's non-text ≥3:1 floor). It used
        // to be redeclared here as a flat #64748B; that second literal
        // shadowed the themed value, so the token is defined once, above.

        // Switch/Toggle THUMB, per design.md §10 (#2305). The thumb is the
        // state indicator, so it must contrast with its own track — not with
        // the page. A single `bg-white` thumb (what shipped before) is
        // invisible on the Off track in light mode, where that track is
        // `cog-surface` = pure white: the control collapses to an empty
        // outlined pill and only the border hints that it is a switch at all.
        // The §10 table has always specified a DARK thumb for light-mode Off;
        // these are those literal values, with `-dark` siblings for the
        // inverted theme (same pattern as cog-border-dark-emphasized above).
        // Measured against their own tracks: 7.5:1 light-Off, 6.3:1 dark-Off,
        // 7.8:1 light-On, 8.9:1 dark-On — every state clears WCAG 1.4.11's
        // ≥3:1 non-text floor with room to spare.
        "cog-switch-thumb-off": "#475569",
        "cog-switch-thumb-off-dark": "#94A3B8",
        // On-thumb in light mode is plain white (`bg-white`); only dark needs
        // a token, since a white thumb on the light-blue dark On track would
        // measure 1.9:1.
        "cog-switch-thumb-on-dark": "#0F172A",
        // Disabled is 1.4.11-EXEMPT, so these deliberately sit lower (2.3:1
        // light / 3.2:1 dark) — visible enough to read as a control, muted
        // enough to read as inactive. Still never white: the disabled track
        // is `cog-surface-muted`, near-white in light mode, so a white thumb
        // would vanish exactly the way the Off one did.
        "cog-switch-thumb-disabled": "#94A3B8",
        "cog-switch-thumb-disabled-dark": "#64748B",

        // Off TRACK in dark mode — design.md §10 specifies #1A2230, a touch
        // lifted from `cog-surface-dark` so the Off track reads as a distinct
        // control rather than a hole cut in the card behind it.
        "cog-switch-track-off-dark": "#1A2230",

        // ── Brand ramps — literal values; mode picks the stop ───────────
        "cog-blue": {
          50: "#EEF5FF",
          100: "#D9E8FF",
          200: "#B5D2FE",
          300: "#9DB4FF", // dark-mode primary (Indigo Atlas refresh)
          400: "#5089F6",
          500: "#3B5BE8",
          600: "#2742C9", // light primary — Indigo (white-on = 7.4:1)
          700: "#1E3499",
          800: "#1E40AF",
          900: "#0F2A6B",
          950: "#172554",
        },
        "cog-amber": {
          50: "#FFFBEB",
          100: "#FEF3C7",
          200: "#FDE68A",
          300: "#FCD34D",
          400: "#FBBF24", // dark focus ring + warning text on dark
          500: "#F59E0B",
          600: "#D97706",
          700: "#B45309", // light warning text + AI gradient end stop
          950: "#451A03",
          // dark-mode bg tint anchor, mirrors cog-danger/cog-warning's own
          // "dark-bg" key (Timeline "executing" event-card shell, #2190).
          "dark-bg": "#1C1200",
        },

        // ── Accent system (Indigo Atlas) — closed 3-accent palette ──────
        // Verticals pick from {indigo (cog-blue), teal, violet}; nobody
        // improvises a fourth. See design.md §1.3.
        // Teal = secondary / data / Dialogue + Files.
        "cog-teal": {
          50: "#ECFDF8",
          100: "#CFFAEC",
          200: "#99F0D6",
          300: "#5BD9B8", // dark-mode fg (9.1:1 on dark surface)
          400: "#14B89A",
          500: "#0E9B82",
          600: "#0B7A66", // light text/UI (4.9:1 on white)
          700: "#086452", // emphasis (6.6:1)
          900: "#0C2E2A", // dark-mode accent-bg tint (Voice Profile teal accent)
        },
        // Violet = tertiary / Range + AI-adjacent (anchored on the AI
        // gradient's existing #6D28D9 midpoint, so it's already in-family).
        "cog-violet": {
          50: "#F5F0FF",
          100: "#EBE0FF",
          200: "#D6C2FF",
          300: "#B794FF", // dark-mode fg (#C4B5FD also available below)
          400: "#9560F5",
          500: "#7C3AED",
          600: "#6D28D9", // light text/UI (6.9:1 on white)
          700: "#5B21B6", // emphasis (9.0:1)
          // dark-mode hero-bg tint (Propaganda Analysis output hero, mirrors
          // the role cog-teal-900 plays for Voice Profile's hero — see
          // docs/design/design.md §16).
          900: "#241A3D",
          "dark-fg": "#C4B5FD", // 9.6:1 on dark surface
        },
        // Sky — reserved for the Studio Media-tools pill switcher's
        // per-item hue dots ONLY (Text to Speech = teal, Audio to Text =
        // sky, Video to Text = violet), mirroring cog-orange's own framing
        // immediately below: NOT a 4th vertical accent (design.md §1.3's
        // closed 3-accent palette for verticals is unchanged) — a single-
        // purpose decorative ramp, same category as orange's
        // severity-signaling carve-out. Shape mirrors cog-teal's (numbered
        // 50-900, no irregular "dark-fg" key).
        "cog-sky": {
          50: "#F0F9FF",
          100: "#E0F2FE",
          200: "#BAE6FD",
          300: "#7DD3FC", // dark-mode fg
          400: "#38BDF8",
          500: "#0EA5E9",
          600: "#0284C7", // decorative dot fill (not a text-contrast anchor)
          700: "#0369A1", // light text/UI (7.3:1 on white)
          900: "#0C4A6E", // dark-mode accent-bg tint, mirrors teal-900/violet-900
        },
        // Fourth accent stop reserved for severity/threat signaling ONLY —
        // NOT a 4th vertical accent (design.md §1.3's closed 3-accent palette
        // for verticals is unchanged). Used by Propaganda Analysis' 4-level
        // threat badge ("high") and any future high-severity indicator.
        // Anchors: light bg #FFEAD5, light fg/text #C2410C (>=4.5:1 on
        // white), dark fg #FB923C, dark bg #3A230A — the rest of the ramp is
        // interpolated around those, mirroring cog-amber's numbered-stop
        // shape plus the dark-bg/dark-fg/dark-border keys the status ramps
        // (cog-danger/cog-success/cog-warning) carry.
        "cog-orange": {
          50: "#FFEAD5",
          100: "#FDD9B0",
          200: "#FCC488",
          300: "#FBA860",
          400: "#FB923C", // dark-mode fg anchor
          500: "#F2740D",
          600: "#D85F0A",
          700: "#C2410C", // light text/UI anchor (4.5:1+ on white)
          950: "#3A230A", // dark-mode bg tint anchor
          "dark-fg": "#FB923C",
          "dark-bg": "#3A230A",
          "dark-border": "#D85F0A",
        },

        // Monitor Posts-tile accent (added for #1128). Pink/rose had no
        // representation in the design system before this — `cog-rose` was
        // the REMOVED legacy X/Kite like-heart token (#E0245E) and stays
        // gone; this is a distinct, newly-introduced token. Same
        // anchor-a-few-values-then-interpolate shape as `cog-orange`:
        // anchors are light bg #FFE4E9 (50), light accent #BE123C (600),
        // light text/UI #9F1239 (700, ~8:1 on white), dark-mode accent stop
        // #FDA4B8 (400), dark-mode bg tint #3B0F1C (950); 100/200/300/500
        // interpolated between those anchors. The actual dark-mode
        // foreground rendered via `text-cog-pink-dark-fg` is the separate
        // `dark-fg` entry, #FECDD8 — lighter than the 400 stop for contrast
        // on the dark surface.
        "cog-pink": {
          50: "#FFE4E9",
          100: "#FFD4DD",
          200: "#FEC4D1",
          300: "#FEB4C5",
          400: "#FDA4B8", // dark-mode accent stop
          500: "#DE5B7A",
          600: "#BE123C", // light accent anchor
          700: "#9F1239", // light text/UI anchor (~8:1 on white)
          950: "#3B0F1C", // dark-mode bg tint anchor
          "dark-fg": "#FECDD8", // dark-mode fg anchor (text-cog-pink-dark-fg)
          "dark-bg": "#3B0F1C",
          "dark-border": "#BE123C",
        },

        // ── Status ramps ────────────────────────────────────────────────
        "cog-success": {
          50: "#D9F2E6",
          200: "#9BD4B5",
          300: "#34D399",
          400: "#3BAA79",
          500: "#075F3D",
          600: "#0B7A50",
          700: "#054A2F",
          800: "#0B7A50",
          950: "#0B2F22",
          dark: "#34D399",
          "dark-bg": "#0B2F22",
          "dark-border": "#0B7A50",
        },
        // cog-green is the long-standing alias for cog-success used by
        // dialogue + range components (cog-green-* classes). Kept in sync.
        "cog-green": {
          50: "#D9F2E6",
          200: "#9BD4B5",
          300: "#6EC29A",
          400: "#3BAA79",
          500: "#075F3D",
          600: "#0B7A50",
          700: "#054A2F",
          800: "#0B7A50",
          900: "#0B2F22",
          dark: "#34D399",
          "dark-bg": "#0B2F22",
        },
        // cog-warning carries BOTH a CSS-variable DEFAULT (range's bare
        // `text-cog-warning`) and the literal ramp (shell/admin/files
        // `cog-warning-500` etc.) so neither shape regresses.
        "cog-warning": {
          DEFAULT: "rgb(var(--cog-warning) / <alpha-value>)",
          50: "#FEF3C7",
          200: "#FDE68A",
          300: "#FBBF24",
          400: "#FBBF24",
          500: "#7C3D08",
          600: "#FBBF24",
          700: "#B45309",
          800: "#B45309",
          950: "#3A2A0A",
          "dark-bg": "#3A2A0A",
          "dark-text": "#FBBF24",
          "dark-border": "#B45309",
        },
        "cog-danger": {
          50: "#FCDCDC",
          200: "#F5A0A0",
          300: "#F5A0A0",
          400: "#EF6868",
          500: "#9B1414",
          600: "#7A0F0F",
          700: "#5C0B0B",
          800: "#9B1414",
          950: "#3A1414",
          dark: "#FCA5A5",
          "dark-bg": "#3A1414",
          "dark-border": "#9B1414",
        },
        "cog-info": {
          50: "#EEF5FF",
          200: "#B5D2FE",
          300: "#83B3FC",
          500: "#163FAD",
          700: "#163FAD",
          800: "#1A4FD6",
          950: "#0E1A33",
          "dark-bg": "#0E1A33",
          "dark-text": "#83B3FC",
          "dark-border": "#1A4FD6",
        },

        // ── Cross-vertical tokens (Task 0.12) ───────────────────────────
        // `commons-accent` was defined byte-identically in commons-mfe's and
        // range-mfe's local tailwind.config.ts (rebrand Epic #267 / #1886)
        // and is consumed cross-vertically by range-mfe's ComposeTab.tsx —
        // promoted here instead of staying duplicated per-MFE. The
        // `--commons-accent` CSS variable itself stays declared per-MFE
        // (each MFE's canvas picks its own RGB triple in src/styles/index.css).
        "commons-accent": "rgb(var(--commons-accent) / <alpha-value>)",
      // contact-group colours (design board 1a98b219) — moved here from the per-MFE tailwind.config.ts
      // so the shared preset stays the single source of truth.,
      // contact-group colours (design board 1a98b219) — moved here from the per-MFE
      // tailwind.config.ts so the shared preset stays the single source of truth.
      "gc-slate-bg": "#F1F5F9",
      "gc-slate-text": "#334155",
      "gc-slate-border": "#CBD5E1",
      "gc-slate-dark-bg": "#1E293B",
      "gc-slate-dark-text": "#CBD5E1",
      "gc-slate-dark-border": "#475569",
      "gc-red-bg": "#FEF2F2",
