      keyframes: {
        // Overlay/content fade (Dialog, Drawer, Popover, HoverCard, menus, Tooltip)
        "fade-in":  { "0%": { opacity: "0" }, "100%": { opacity: "1" } },
        "fade-out": { "0%": { opacity: "1" }, "100%": { opacity: "0" } },

        // Modal/popover scale-with-fade (Dialog, AlertDialog, Popover, HoverCard).
        // The keyframe `transform` REPLACES the element's transform utilities
        // for the animation's duration, and the `both` fill persists the final
        // frame — a bare scale() would permanently strip a Dialog panel's
        // -translate-x-1/2 centering (panel renders half off-screen). Compose
        // the Tailwind translate vars so the utility's translation survives
        // every frame (var() in keyframes resolves against the animated element).
        "zoom-in-95":  {
          "0%":   { opacity: "0", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(0.95)" },
          "100%": { opacity: "1", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(1)" },
        },
        "zoom-out-95": {
          "0%":   { opacity: "1", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(1)" },
          "100%": { opacity: "0", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(0.95)" },
        },

        // Centered dialog panel scale-with-fade (Dialog, AlertDialog).
        // A keyframe `transform` REPLACES the element's transform utilities for
        // the animation's duration, and fill-mode `both` persists the final
        // frame — so the keyframe must carry whatever translate the panel
        // declares or its centering is wiped. The `default`/AlertDialog panels
        // center horizontally only (`left-1/2 -translate-x-1/2`), while the
        // `wide` variant ALSO centers vertically (`top-1/2 -translate-y-1/2`).
        // Composing BOTH Tailwind translate vars keeps either centering intact
        // every frame: a translateX(-50%)-only keyframe stripped the wide
        // variant's -translate-y-1/2 and parked its top edge at 50vh, spilling
        // the footer off-screen (#1539). `--tw-translate-y` falls back to 0 for
        // panels that declare no Y translate, so default/AlertDialog are
        // unchanged. Mirrors the zoom-in-95/zoom-out-95 guarantee above.
        "dialog-zoom-in": {
          "0%":   { opacity: "0", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(0.95)" },
          "100%": { opacity: "1", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(1)" },
        },
        "dialog-zoom-out": {
          "0%":   { opacity: "1", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(1)" },
          "100%": { opacity: "0", transform: "translate(var(--tw-translate-x, 0), var(--tw-translate-y, 0)) scale(0.95)" },
        },

        // Menu / Tooltip directional entrance — pairs with data-[side=*] selectors
        "slide-in-from-top-2": {
          "0%":   { opacity: "0", transform: "translateY(-8px)" },
          "100%": { opacity: "1", transform: "translateY(0)" },
        },
        "slide-in-from-bottom-2": {
          "0%":   { opacity: "0", transform: "translateY(8px)" },
          "100%": { opacity: "1", transform: "translateY(0)" },
        },
        "slide-in-from-left-2": {
          "0%":   { opacity: "0", transform: "translateX(-8px)" },
          "100%": { opacity: "1", transform: "translateX(0)" },
        },
        "slide-in-from-right-2": {
          "0%":   { opacity: "0", transform: "translateX(8px)" },
          "100%": { opacity: "1", transform: "translateX(0)" },
