        "dialog-zoom-in":  "dialog-zoom-in 220ms cubic-bezier(0.16,1,0.3,1) both",
        "dialog-zoom-out": "dialog-zoom-out 150ms ease-in both",

        // Directional menu/tooltip entrances
        "slide-in-from-top-2":    "slide-in-from-top-2 150ms cubic-bezier(0.16,1,0.3,1) both",
        "slide-in-from-bottom-2": "slide-in-from-bottom-2 150ms cubic-bezier(0.16,1,0.3,1) both",
        "slide-in-from-left-2":   "slide-in-from-left-2 150ms cubic-bezier(0.16,1,0.3,1) both",
