import type { Config } from "tailwindcss";

// ─────────────────────────────────────────────────────────────────────────
// CogOS 3.0 shared Tailwind preset — single source of truth for the cog-*
// design-system tokens consumed by every MFE.
//
// See docs/design/design.md §16 for the canonical token mapping. This preset
// is the UNION SUPERSET of the five previously-drifted per-MFE tailwind
// configs (shell / admin / dialogue / files / range): every token any MFE
// defined is present here so no MFE loses a token when it switches to
// `presets: [cogPreset]`.
//
// Theme-switchable colors (surfaces, text, borders, focus, the bare
// `cog-warning` DEFAULT) read CSS variables defined per-MFE in
// src/styles/index.css and are written `rgb(var(--token) / <alpha-value>)`
// so Tailwind's opacity utilities work. Brand + status ramps are literal
// values; components pick the right stop per mode via the `dark:` variant.
//
// Conflict notes (values that differed across MFEs, resolved here):
//   • cog-success.300 → #34D399  (admin's value; the only MFE that uses the
//     300 stop — dialogue/range use cog-green-300 instead, unaffected).
//   • cog-danger.700  → #5C0B0B  (majority: dialogue/files/range). admin
//     uses #7A0F0F and keeps a one-line local override in its own config.
//   • cog-blue.900    → #0F2A6B  (range's value; serves both the light-mode
//     `text-cog-blue-900` and the dark-mode `bg-cog-blue-900/20` call sites
//     that previously rendered nothing where the stop was undefined).
//   • cog-green.900   → #0B2F22  (matches the dark-bg tint dialogue/range
//     were already approximating via `dark:bg-[#0B2F22]`).
// ─────────────────────────────────────────────────────────────────────────

const cogPreset = {
  darkMode: ["variant", [
    "&:where(.dark, .dark *)",
    '&:where([data-theme="dark"], [data-theme="dark"] *)',
  ]],
  theme: {
    extend: {
      colors: {
        // ── Theme-switchable (CSS-variable) tokens ──────────────────────
        "cog-canvas": "rgb(var(--cog-canvas) / <alpha-value>)",
        "cog-surface": "rgb(var(--cog-surface) / <alpha-value>)",
        "cog-surface-subtle": "rgb(var(--cog-surface-subtle) / <alpha-value>)",
        "cog-surface-muted": "rgb(var(--cog-surface-muted) / <alpha-value>)",
        "cog-skeleton": "rgb(var(--cog-skeleton) / <alpha-value>)",
        "cog-text-primary": "rgb(var(--cog-text-primary) / <alpha-value>)",
        "cog-text-secondary": "rgb(var(--cog-text-secondary) / <alpha-value>)",
        "cog-text-tertiary": "rgb(var(--cog-text-tertiary) / <alpha-value>)",
        "cog-text-eyebrow": "rgb(var(--cog-text-eyebrow) / <alpha-value>)",
        "cog-border": "rgb(var(--cog-border) / <alpha-value>)",
        "cog-divider": "rgb(var(--cog-divider) / <alpha-value>)",
        "cog-focus": "rgb(var(--cog-focus) / <alpha-value>)",

        // Task 5.2: theme-aware 3rd border tier (stronger than cog-border,
        // ≥3:1 in both themes) — CSS-variable backed like cog-border/
        // cog-divider above, unlike the static dark-only token below. Ready
        // for range-mfe's `cog-border-strong` call sites (BentoGrid.tsx,
        // FocusCanvas.tsx :264/:311), which reference a class that doesn't
        // exist yet — migrating those sites is Task 2.5a/7.3's, not this one's.
        "cog-border-emphasized": "rgb(var(--cog-border-emphasized) / <alpha-value>)",

        // Dark-only emphasized border (design.md §6 e4/e5). Always use with
        // a `dark:` prefix — not a CSS variable because it is dark-mode only.
        // Task 5.2: raised #3F4A60 (1.16-2.17:1, failed the 3:1 floor) to
        // #94A3B8 (5.97-7.53:1) — the same value cog-border-emphasized
        // carries for dark mode above.
        "cog-border-dark-emphasized": "#94A3B8",
        "cog-scrim": "rgba(15,23,42,0.45)",
        "cog-scrim-dark": "rgba(0,0,0,0.65)",

